            "created_at": datetime.utcnow().isoformat(),
            "expires_at": (datetime.utcnow() + timedelta(hours=AuthConfig.JWT_EXPIRY_HOURS)).isoformat()
        }

        return {"success": True, "token": token, "message": "Login successful"}

    def create_token(self, user):
        payload = {
            "user_id": user.username,
            "exp": datetime.utcnow()
        }
        token = jwt.encode(payload, AuthConfig.SECRET_KEY, algorithm=AuthConfig.JWT_ALGORITHM)

    def get_current_user(self, token):
        if token not in self.sessions:
            return {"success": False, "message": "Invalid token"}

        session = self.sessions[token]
        if datetime.utcnow().isoformat() > session["expires_at"]:
            del self.sessions[token]
            return {"success": False, "message": "Token expired"}

