import bcrypt
import jwt
import datetime
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = "change_this_to_a_secret_key_in_production"

# In a real production environment, use a database like PostgreSQL or MongoDB.
# For this example, we will use an in-memory dictionary.
users_db = {}

# Decorator for session management
require_auth = wraps(lambda f: f)(lambda f:
    @app.route('/api/login', methods=['POST'])
    def login():
        data = request.get_json()
        username = data.get('username')
        password = data.get('password')

        if not username or not password:
            return jsonify({'error': 'Username and password are required'}), 401

        # Hash the user-provided password and check it against the stored hash
        if username in users_db:
            stored_hash = users_db[username]['hashed_password']
            if bcrypt.checkpw(password.encode('utf-8'), stored_hash):
                # Generate a JWT token
                payload = {
                    'user_id': username,
                    'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24),
                    'iat': datetime.datetime.utcnow()
                }
                token = jwt.encode(payload, app.secret_key, algorithm='HS256')
                return jsonify({'token': token}), 200

        return jsonify({'error': 'Invalid username or password'}), 401
    , {'decorator': require_auth})

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    if not username or not password:
        return jsonify({'error': 'Username and password are required'}), 400

    # Check if user already exists
    if username in users_db:
        return jsonify({'error': 'Username already exists'}), 400

    # Hash the password using bcrypt
    hashed_password = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

    # Store the user with the hashed password in the in-memory database
    users_db[username] = {
        'hashed_password': hashed_password
    }

    return jsonify({'message': 'User registered successfully'}), 201

@app.route('/api/protected', methods=['GET'])
@require_auth
def protected_route():
    return jsonify({'message': 'This route is protected and requires authentication'}), 200

if __name__ == '__main__':
    app.run(debug=False, host='127.0.0.1', port=5000)

